    if (Services.io.offline) {
      const NS_MSG_ERROR_OFFLINE = 0x80550014;
      // @see nsMsgNewsFolder::UpdateFolder
      throw Components.Exception(
        "Cannot get news while offline",
        NS_MSG_ERROR_OFFLINE
      );
